import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { updateChat } from "../../../api/mutations/lastOpenedChat";
import { useContext, useEffect } from "react";
import Chat from "../../../components/chat/Chat";
import { getChatPath } from "../../../api/queries/getChatPath";
import Loading from "../../../assets/Loading";
import { GlobalContext } from "../../../App";

export interface QueryFilter {
    structureId?: string;
    name?: string;
    type?: "FOLDER" | "CHAT";
}

export const Route = createFileRoute("/_chatLayout/chat/$id")({
    validateSearch: (search: Record<string, unknown>): QueryFilter => {
        return {
            structureId: search.structureId as string,
            name: search.name as string,
            type: search.type as "CHAT" | "FOLDER",
        };
    },
    component: RouteComponent,
    pendingComponent: () => <Loading />,
});

function RouteComponent() {
    const navigate = useNavigate();
    const { id } = Route.useParams();
    const { data: chatPath, error } = getChatPath(id);
    const setLastOpenedChat = updateChat();
    const update = updateChat();
    const { setStructureToDelete, setChatId } = useContext(GlobalContext);
    const structureData = Route.useSearch();

    useEffect(() => {
        if (!id) {
            navigate({ to: "/chat" });
            return;
        }
        if (error) {
            navigate({ to: "/chat" });
            setLastOpenedChat.mutate(null);
            setChatId(null);
            return;
        }
        setChatId(id);
    }, [id, error]);

    useEffect(() => {
        if (structureData && structureData.structureId) {
            setStructureToDelete({
                id: structureData.structureId,
                name: structureData.name,
                type: structureData.type,
            });
        }
    }, [structureData]);

    const handleClose = () => {
        update.mutate(null, {
            onSuccess: () => {
                navigate({ to: "/chat" });
            },
        });
    };

    return (
        <div className="appear w-full max-w-full flex flex-col bg-zinc-900">
            <div className="chat_header w-full flex items-center justify-between text-extralight px-8 py-2 shadow-[0px_0px_8px_0px_rgb(0,0,0)]">
                <span className="text-sm">
                    {chatPath && chatPath.join(" ⭢ ")}
                </span>
                <button
                    className="text-xl cursor-pointer hover:bg-zinc-800 px-4 py-2 rounded-xl transition-[background] duration-300 ease-in-out"
                    onClick={() => handleClose()}
                >
                    Zamknij
                </button>
            </div>
            <Chat chatId={id} />
        </div>
    );
}
